select t.lc_id,t.lc_id lcId,t.current_people_num,t.current_people_num
currentPeopleNum,t.leave_people_num,t.leave_people_num leavePeopleNum,t.have_bicycle,t.have_bicycle
haveBicycle,t.lift_door_state,t.lift_door_state liftDoorState,t.warn_type,t.warn_type
warnType,t.lift_operate_state,t.lift_operate_state liftOperateState,t.status_cd,t.status_cd
statusCd,t.current_speed,t.current_speed currentSpeed,t.alarm_in_polarity,t.alarm_in_polarity
alarmInPolarity,t.lw_id,t.lw_id lwId,t.lift_name,t.lift_name liftName,t.warn_time,t.warn_time
warnTime,t.enter_people_num,t.enter_people_num enterPeopleNum,t.warn_img,t.warn_img
warnImg,t.lift_machine_id,t.lift_machine_id liftMachineId,t.camera_code,t.camera_code
cameraCode,t.community_id,t.community_id communityId,t.camera_name,t.camera_name cameraName
from lift_warn t
where 1 =1

    and t.lc_id= #{lcId}


    and t.current_people_num= #{currentPeopleNum}


    and t.leave_people_num= #{leavePeopleNum}


    and t.have_bicycle= #{haveBicycle}


    and t.lift_door_state= #{liftDoorState}


    and t.warn_type= #{warnType}


    and t.lift_operate_state= #{liftOperateState}


    and t.status_cd= #{statusCd}


    and t.current_speed= #{currentSpeed}


    and t.alarm_in_polarity= #{alarmInPolarity}


    and t.lw_id= #{lwId}


    and t.lift_name= #{liftName}


    and t.warn_time= #{warnTime}


    and t.enter_people_num= #{enterPeopleNum}


    and t.warn_img= #{warnImg}


    and t.lift_machine_id= #{liftMachineId}


    and t.camera_code= #{cameraCode}


    and t.community_id= #{communityId}


    and t.camera_name= #{cameraName}

order by t.create_time desc

    limit #{page}, #{row}

